const ExcelJS = require('exceljs');

const item = $input.first();
const binary = item.binary || {};
const binaryKeys = Object.keys(binary);
if (binaryKeys.length === 0) throw new Error('Webhook received no binary data. Upload with: curl -X POST <url> -F "data=@file.xlsx"');

const fieldName = binary['data'] ? 'data' : binaryKeys[0];
const binaryMeta = binary[fieldName];
if (!binaryMeta || typeof binaryMeta.data !== 'string') throw new Error('Binary field "' + fieldName + '" has unexpected structure: ' + JSON.stringify(binaryMeta).substring(0, 200));

const looksLikeId = binaryMeta.data.length < 100 && /^[a-f0-9-]+$/i.test(binaryMeta.data.trim());
if (looksLikeId) throw new Error('n8n is running in filesystem binary mode. Add N8N_BINARY_DATA_MODE=default AND N8N_DEFAULT_BINARY_DATA_MODE=default to docker-compose and restart.');

const buffer = Buffer.from(binaryMeta.data, 'base64');
if (buffer.length < 4 || buffer[0] !== 0x50 || buffer[1] !== 0x4B) throw new Error('Not a valid .xlsx file. .xls is not supported — save as .xlsx first.');

function getCellText(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'string') { var s = v.trim(); return s || null; }
  if (v && typeof v === 'object') {
    if (typeof v.getTime === 'function') return v.toISOString();
    if (v.richText) { var s = v.richText.map(function(r){return r.text;}).join('').trim(); return s || null; }
    if (v.text != null) { var t = typeof v.text === 'string' ? v.text : (v.text.richText ? v.text.richText.map(function(r){return r.text;}).join('') : String(v.text)); return t.trim() || null; }
    if (v.result !== undefined) return v.result != null ? String(v.result).trim() || null : null;
    if (v.formula !== undefined) return null;
  }
  return String(v).trim() || null;
}

var SKIP_ROW_PATS = [/\bvoorbeeld\b/i, /\bexemple\b/i, /\bexample\b/i, /\bcontrole\b/i, /\bonderliggende\b/i];
var SKU_COL_PATS = [
  /^sku$/i,
  /\bartikel(?:nr|num(?:mer)?|ref(?:erentie)?|code)\b/i,
  /\bref\.?\s*(?:leverancier|article|art\.?|fournisseur)\b/i,
  /^EINA-IDNLF$/i, /^MARA-MATNR$/i,
  /\barticle\s*(?:nr|num(?:ber)?|no\.?|code|ref)\b/i,
  /\bproduct\s*(?:code|num(?:ber)?|ref)\b/i,
  /\bitem\s*(?:code|num(?:ber)?|ref)\b/i
];

function rowIsSkip(texts) {
  return SKIP_ROW_PATS.some(function(p){ return texts.slice(0, 3).some(function(t){ return p.test(t); }); });
}

function isBarrierRow(ri) {
  var col1 = ri.cells.find(function(x){ return x.c === 1; });
  return !!(col1 && SKIP_ROW_PATS.some(function(p){ return p.test(col1.t); }) && ri.filled >= 5);
}

function sapCodeScore(texts) {
  if (!texts.length) return 0;
  var n = texts.filter(function(t){ return /^[A-Z][A-Z0-9]{1,9}(-[A-Z][A-Z0-9]{1,9})?(\([A-Z0-9_()+]+\))?$/.test(t); }).length;
  return n / texts.length;
}

const workbook = new ExcelJS.Workbook();
await workbook.xlsx.load(buffer);
const worksheet = workbook.worksheets[0];
const totalRows = worksheet.rowCount;

let maxCols = 0;
for (let r = 1; r <= Math.min(50, totalRows); r++) {
  for (let c = 200; c >= 1; c--) {
    if (getCellText(worksheet.getRow(r).getCell(c).value) !== null) { if (c > maxCols) maxCols = c; break; }
  }
}
if (maxCols === 0) throw new Error('Excel sheet appears empty in first 50 rows');

var rowInfo = [];
for (let r = 1; r <= Math.min(100, totalRows); r++) {
  var cells = []; var filled = 0;
  for (let c = 1; c <= maxCols; c++) {
    var t = getCellText(worksheet.getRow(r).getCell(c).value);
    if (t !== null) { filled++; cells.push({ c: c, t: t }); }
  }
  var texts = cells.map(function(x){ return x.t; });
  rowInfo.push({ r: r, filled: filled, ratio: filled / maxCols, cells: cells, texts: texts, isSkip: rowIsSkip(texts) });
}

var lastBarrierRow = 0;
for (var ri of rowInfo) {
  if (ri.r > 50) break;
  if (isBarrierRow(ri)) lastBarrierRow = ri.r;
}

var dataStartRow;
if (lastBarrierRow > 0) {
  dataStartRow = lastBarrierRow + 1;
  while (dataStartRow <= totalRows) {
    var riFwd = rowInfo.find(function(x){ return x.r === dataStartRow; });
    if (!riFwd || riFwd.filled > 0) break;
    dataStartRow++;
  }
} else {
  var firstDense = rowInfo.find(function(ri){ return ri.ratio >= 0.5; })
    || rowInfo.find(function(ri){ return ri.ratio >= 0.3; })
    || rowInfo.find(function(ri){ return ri.filled > 0; });
  if (!firstDense) throw new Error('No header row detected');
  var threshold = Math.max(0.3, firstDense.ratio * 0.8);
  var lastCluster = firstDense.r;
  dataStartRow = firstDense.r + 1;
  for (var ri2 of rowInfo) {
    if (ri2.r <= firstDense.r || ri2.r > firstDense.r + 20) continue;
    if (ri2.ratio > threshold) { lastCluster = ri2.r; }
    else if (ri2.filled > 0 && getCellText(worksheet.getRow(ri2.r).getCell(1).value) !== null) { dataStartRow = ri2.r; break; }
  }
  if (dataStartRow === firstDense.r + 1 && lastCluster > firstDense.r) {
    dataStartRow = lastCluster + 1;
    for (var ri3 of rowInfo) {
      if (ri3.r >= dataStartRow && ri3.r <= dataStartRow + 5 && ri3.filled > 0) { dataStartRow = ri3.r; break; }
    }
  }
}

var headerRegion = rowInfo.filter(function(ri){ return ri.r < dataStartRow && !ri.isSkip && ri.filled >= 2; });
if (headerRegion.length === 0) headerRegion = rowInfo.filter(function(ri){ return ri.r < dataStartRow && ri.filled >= 1; });
if (headerRegion.length === 0) throw new Error('No header row found (dataStartRow=' + dataStartRow + ', totalRows=' + totalRows + ')');
var bestHeader = headerRegion.reduce(function(best, ri) {
  var s = sapCodeScore(ri.texts), bs = sapCodeScore(best.texts);
  return (s > bs || (s === bs && ri.filled > best.filled)) ? ri : best;
}, headerRegion[0]);
var headerRowIndex = bestHeader.r;

var hintMap = {};
var firstDenseInRegion = headerRegion.find(function(ri){ return ri.ratio >= 0.5 && ri.r !== headerRowIndex; });
var hintSource = firstDenseInRegion || rowInfo.find(function(ri){ return ri.r === headerRowIndex - 1 && !ri.isSkip; });
if (hintSource) {
  hintSource.cells.forEach(function(x){ hintMap[x.c] = x.t; });
}

var headerCols = bestHeader.cells.map(function(x) {
  var entry = { header: x.t, colNum: x.c };
  if (hintMap[x.c]) entry.hint = hintMap[x.c];
  return entry;
});

var skuColNum = null;
for (var col of headerCols) {
  if ([col.header, col.hint || ''].some(function(t){ return SKU_COL_PATS.some(function(p){ return p.test(t); }); })) { skuColNum = col.colNum; break; }
}
if (skuColNum === null) {
  var sample = rowInfo.filter(function(ri){ return ri.r >= dataStartRow && !ri.isSkip; }).slice(0, 20);
  var bestScore = -1;
  for (var col2 of headerCols) {
    var vals = sample.map(function(ri){ var x = ri.cells.find(function(c){ return c.c === col2.colNum; }); return x ? x.t : null; }).filter(function(v){ return v !== null; });
    if (!vals.length) continue;
    var unique = new Set(vals).size;
    var alnum = vals.filter(function(v){ return /^[A-Za-z0-9_.\-]+$/.test(v) && v.length <= 20; }).length;
    var score = (unique / vals.length) * (alnum / vals.length) * (vals.length / Math.max(sample.length, 1));
    if (score > bestScore) { bestScore = score; skuColNum = col2.colNum; }
  }
}
if (skuColNum === null) skuColNum = 1;

var rows = [];
for (let r = dataStartRow; r <= totalRows; r++) {
  var firstCells = [];
  for (let c = 1; c <= Math.min(maxCols, 5); c++) { var ft = getCellText(worksheet.getRow(r).getCell(c).value); if (ft) firstCells.push(ft); }
  if (rowIsSkip(firstCells)) continue;
  var sku = getCellText(worksheet.getRow(r).getCell(skuColNum).value);
  if (sku === null) continue;
  rows.push({ sku: sku, rowNum: r });
}

const originalBuffer = buffer.toString('base64');
const originalFileName = binaryMeta.fileName || 'enriched.xlsx';
return [{ json: { headerCols: headerCols, headerRowIndex: headerRowIndex, dataStartRow: dataStartRow, rows: rows, originalBuffer: originalBuffer, originalFileName: originalFileName } }];

const ExcelJS = require('exceljs');
const https = require('https');
const http = require('http');
const { URL } = require('url');

const AKENEO_BASE_URL = $env.AKENEO_BASE_URL;
const AKENEO_CLIENT_ID = $env.AKENEO_CLIENT_ID;
const AKENEO_CLIENT_SECRET = $env.AKENEO_CLIENT_SECRET;
const AKENEO_USERNAME = $env.AKENEO_USERNAME;
const AKENEO_PASSWORD = $env.AKENEO_PASSWORD;
const OPENAI_API_KEY = $env.OPENAI_API_KEY;

if (!AKENEO_BASE_URL)      throw new Error('Missing env var: AKENEO_BASE_URL');
if (!AKENEO_CLIENT_ID)     throw new Error('Missing env var: AKENEO_CLIENT_ID');
if (!AKENEO_CLIENT_SECRET) throw new Error('Missing env var: AKENEO_CLIENT_SECRET');
if (!AKENEO_USERNAME)      throw new Error('Missing env var: AKENEO_USERNAME');
if (!AKENEO_PASSWORD)      throw new Error('Missing env var: AKENEO_PASSWORD');
if (!OPENAI_API_KEY)       throw new Error('Missing env var: OPENAI_API_KEY');

// Columns that must never be written by the AI
var BLOCKED_HEADERS = new Set([
  'MATNR',            // Col D: SAP article number — customer fills this in
  'MEAN-EAN11_1',     // Col H-L: no per-language extra EAN codes for DCM
  'MEAN-EAN11_2',
  'MEAN-EAN11_3',
  'MEAN-EAN11_4',
  'MEAN-EAN11_5',
  'Purchasing price', // Col DU: never set prices
  'STPRS',            // Col EH: standard price
  'Sales price 1',    // Col DY
  'Sales price 2',    // Col DZ
  'Sales price 3',    // Col EA
  'VKP0_S600',        // Col EB-EF: sales prices per location
  'VKP0_S601',
  'VKP0_S602',
  'VKP0_S603',
  'VKP0_S604',
]);

// Locale to use when extracting each MAKTX commercial description column
var MAKTX_LOCALES = {
  'MAKTX_NL': 'nl_BE',
  'MAKTX_FR': 'fr_BE',
  'MAKTX_EN': 'en_GB',
  'MAKTX_DE': 'de_DE',
};

// MAKTX columns always read from 'title' attribute (commercial catalog name), never from OpenAI mapping.
var MAKTX_HARDCODED_ATTR = 'title';

// ── getCellText ───────────────────────────────────────────────────────

function getCellText(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'string') { var s = v.trim(); return s || null; }
  if (v && typeof v === 'object') {
    if (typeof v.getTime === 'function') return v.toISOString();
    if (v.richText) { var s = v.richText.map(function(r) { return r.text; }).join('').trim(); return s || null; }
    if (v.text != null) {
      var t = typeof v.text === 'string' ? v.text : (v.text.richText ? v.text.richText.map(function(r) { return r.text; }).join('') : String(v.text));
      return t.trim() || null;
    }
    if (v.result !== undefined) return v.result != null ? String(v.result).trim() || null : null;
    if (v.formula !== undefined) return null;
  }
  return String(v).trim() || null;
}

// ── makeRequest ───────────────────────────────────────────────────────

function makeRequest(url, options) {
  options = options || {};
  return new Promise(function(resolve, reject) {
    var urlObj = new URL(url);
    var isHttps = urlObj.protocol === 'https:';
    var lib = isHttps ? https : http;
    var body = options.body ? Buffer.from(options.body) : null;
    var reqOptions = {
      hostname: urlObj.hostname,
      port: urlObj.port ? Number(urlObj.port) : (isHttps ? 443 : 80),
      path: urlObj.pathname + (urlObj.search || ''),
      method: options.method || 'GET',
      headers: Object.assign({}, options.headers || {})
    };
    if (body) reqOptions.headers['Content-Length'] = body.length;
    var req = lib.request(reqOptions, function(res) {
      var chunks = [];
      res.on('data', function(chunk) { chunks.push(chunk); });
      res.on('end', function() {
        var text = Buffer.concat(chunks).toString('utf8');
        resolve({
          ok: res.statusCode >= 200 && res.statusCode < 300,
          status: res.statusCode,
          json: function() { return Promise.resolve(JSON.parse(text)); },
          text: function() { return Promise.resolve(text); }
        });
      });
      res.on('error', reject);
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

// ── Packing unit helpers ──────────────────────────────────────────────

// Number of base units contained in a packing row (Aantal_CE).
function unitQty(u) { var n = parseFloat(u && u.Aantal_CE); return isNaN(n) ? 0 : n; }

// Assigns the units_by_type rows to Floralux template slots WITHOUT relying on the
// per-product unit_used code (BOT/CS/BAG/KAR/EP… vary by product). Instead it uses the
// structured unit_type ("CE" = consumer/base unit) plus the quantity hierarchy:
//   slot 2 = inner box, 3 = outer carton, 4 = europallet, 5 = truck.
// The base (CE) unit becomes MEINS and gets no packing slot. The remaining rows are ranked
// largest-first: pallet, then outer carton, then inner box (truck only when 4+ levels exist).
function buildSlotMap(productValues) {
  var attrVals = productValues['units_by_type'];
  if (!Array.isArray(attrVals) || attrVals.length === 0) return {};
  var hit = attrVals.find(function(v) { return v.locale === null && v.scope === null; }) || attrVals[0];
  if (!hit || !Array.isArray(hit.data) || hit.data.length === 0) return {};
  var rows = hit.data.slice();
  var base = rows.find(function(u) { return String(u.unit_type || '').toUpperCase() === 'CE'; });
  var rest = base ? rows.filter(function(u) { return u !== base; })
                  : rows.filter(function(u) { return unitQty(u) > 1; });
  if (!base) { var sorted = rows.slice().sort(function(a, b) { return unitQty(a) - unitQty(b); }); base = sorted[0] || null; }
  rest = rest.slice().sort(function(a, b) { return unitQty(b) - unitQty(a); }); // largest first
  var order = rest.length >= 4 ? [5, 4, 3, 2] : [4, 3, 2];
  var map = { base: base };
  rest.forEach(function(u, i) { if (order[i]) map[order[i]] = u; });
  return map;
}

// Returns the article's base unit_used (the CE consumer unit). Used for MEINS so it is never
// overwritten with a weight/content number.
function extractBaseUnit(productValues) {
  var base = buildSlotMap(productValues).base;
  return base && base.unit_used ? base.unit_used : null;
}

// Resolves the country of origin (HERKL) from the product categories:
// Birchmeier products are made in DE; DCM (everything else) is BE.
function resolveHerkl(productValues) {
  var cats = productValues['__categories'];
  if (Array.isArray(cats) && cats.some(function(c) { return /birchmeier|berchemeier/i.test(String(c)); })) return 'DE';
  return 'BE';
}

// Returns a field from the packing unit that belongs to the given slot number.
function extractUnitBySlot(productValues, slotNum, fieldName) {
  var unit = buildSlotMap(productValues)[slotNum];
  if (!unit) return null;
  var val = unit[fieldName];
  return (val !== undefined && val !== null && val !== '') ? val : null;
}

// Date columns (valid-from dates, "hubo", MARA-MSTDV/MSTDE, MARC-MMSTD) are never written —
// the supplier's existing value is left untouched.
var DATE_HEADER_PATS = /\b(MARA-MSTD[EV]|MARC-MMSTD)\b/i;
function isDateColumn(header, hint) {
  var name = (header || '') + ' ' + (hint || '');
  return DATE_HEADER_PATS.test(name) || /ddmm|jjjj|yyyy|datum|geldig van|valid from|hubo/i.test(name);
}

// Fostplus / Recupel / Bebat columns (FOSTPLS_RE, MEME_REC*, MEME_BEB*) are Y/N flags.
// Value comes from a matching Akeneo flag when present, otherwise defaults to N.
var YESNO_HEADER_PATS = /\b(FOSTPLS_RE|MEME_REC\d+A?|MEME_BEB\d+A?)\b/i;
function isYesNoColumn(header, hint) {
  return YESNO_HEADER_PATS.test((header || '') + ' ' + (hint || ''));
}
function toYesNo(v) {
  if (v === true || v === 1) return 'Y';
  if (typeof v === 'string' && /^(true|ja|yes|y|1|x)$/i.test(v.trim())) return 'Y';
  return 'N';
}

function getHardcodedValue(header, hint, productValues) {
  var candidates = [header, hint || ''];
  for (var ci = 0; ci < candidates.length; ci++) {
    var name = candidates[ci]; var m;
    if (/\bMEINS\b/i.test(name)) return extractBaseUnit(productValues);
    if (/\bHERKL\b/i.test(name)) return resolveHerkl(productValues);
    if ((m = /\bMEINH_(\d+)\b/i.exec(name))) return extractUnitBySlot(productValues, +m[1], 'unit_used');
    if ((m = /\bUMREZ_(\d+)\b/i.exec(name))) return extractUnitBySlot(productValues, +m[1], 'Aantal_CE');
    if ((m = /\bEAN11_(\d+)\b/i.exec(name)))  return extractUnitBySlot(productValues, +m[1], 'EAN');
    // Min order quantity = base units per outer carton, else per europallet
    if (/\bEINE-MINBM\b/i.test(name)) {
      var carton = extractUnitBySlot(productValues, 3, 'Aantal_CE');
      return carton !== null ? carton : extractUnitBySlot(productValues, 4, 'Aantal_CE');
    }
  }
  return undefined;
}

// `categories` is injected as a private __categories key so hardcoded rules (HERKL) can read it.
function buildUnitViews(productValues, categories) {
  var base = Object.assign({}, productValues, { __categories: categories || [] });
  var attrVals = base['units_by_type'];
  if (!Array.isArray(attrVals) || attrVals.length === 0) return [{ values: base }];
  var hit = attrVals.find(function(v) { return v.locale === null && v.scope === null; }) || attrVals[0];
  if (!hit || !Array.isArray(hit.data) || hit.data.length <= 1) return [{ values: base }];
  return hit.data.map(function(unitRow) {
    var override = unitRow.EAN ? { ean_ce: [{ locale: null, scope: null, data: String(unitRow.EAN) }] } : {};
    return { values: Object.assign({}, base, override) };
  });
}

// ── helpers ───────────────────────────────────────────────────────────

function extractValue(attrValues) {
  if (!Array.isArray(attrValues) || attrValues.length === 0) return null;
  var hit = attrValues.find(function(v) { return v.locale === null && v.scope === null; })
    || attrValues.find(function(v) { return v.locale === 'en_US'; })
    || attrValues[0];
  if (!hit) return null;
  var data = hit.data;
  if (data && typeof data === 'object' && !Array.isArray(data) && 'amount' in data) {
    var n = parseFloat(data.amount); return isNaN(n) ? data.amount : n;
  }
  if (Array.isArray(data)) {
    if (data.length === 0) return null;
    var first = data[0];
    if (typeof first === 'string') return first;  // e.g. country of origin ["BE"]
    if (first && typeof first === 'object' && 'amount' in first) {
      var n = parseFloat(first.amount); return isNaN(n) ? first.amount : n;
    }
    return String(first);
  }
  return data;
}

// Extracts the value for a specific locale from a localised Akeneo attribute.
function extractLocalizedValue(attrValues, locale) {
  if (!Array.isArray(attrValues) || attrValues.length === 0) return null;
  var hit = attrValues.find(function(v) { return v.locale === locale; });
  if (!hit) {
    var prefix = locale.split('_')[0];
    hit = attrValues.find(function(v) { return v.locale && v.locale.split('_')[0] === prefix; });
  }
  if (!hit) return null;
  var data = hit.data;
  if (typeof data === 'string') return data.trim() || null;
  return data;
}

// Sort variants smallest-first using any numeric quantity attribute.
// This ensures: first row with the SKU = single unit, second row = box, etc.
function sortVariantsBySize(variants) {
  var qtyKeywords = ['qty', 'quantity', 'hoeveelheid', 'aantal', 'menge', 'quantite', 'umrez'];
  function getQty(variant) {
    var entries = Object.entries(variant.values || {});
    for (var i = 0; i < entries.length; i++) {
      var code = entries[i][0]; var vals = entries[i][1];
      if (qtyKeywords.some(function(kw) { return code.toLowerCase().indexOf(kw) !== -1; })) {
        var val = vals && vals[0] && vals[0].data;
        if (typeof val === 'number') return val;
        if (typeof val === 'string' && !isNaN(parseFloat(val))) return parseFloat(val);
      }
    }
    return 0;
  }
  return variants.slice().sort(function(a, b) { return getQty(a) - getQty(b); });
}

// ── Akeneo ────────────────────────────────────────────────────────────

async function getAkeneoToken() {
  var credentials = Buffer.from(AKENEO_CLIENT_ID + ':' + AKENEO_CLIENT_SECRET).toString('base64');
  var res = await makeRequest(AKENEO_BASE_URL + '/api/oauth/v1/token', {
    method: 'POST',
    headers: { 'Authorization': 'Basic ' + credentials, 'Content-Type': 'application/json' },
    body: JSON.stringify({ grant_type: 'password', username: AKENEO_USERNAME, password: AKENEO_PASSWORD })
  });
  if (!res.ok) { var b = await res.text(); throw new Error('Akeneo token failed: ' + res.status + ' ' + b); }
  var data = await res.json();
  if (!data.access_token) throw new Error('Akeneo OAuth response missing access_token');
  return data.access_token;
}

async function fetchAkeneoAttributes(token) {
  var attributes = [];
  var nextUrl = AKENEO_BASE_URL + '/api/rest/v1/attributes?limit=100&with_count=false';
  var pages = 0;
  while (nextUrl && pages < 50) {
    var res = await makeRequest(nextUrl, { headers: { Authorization: 'Bearer ' + token } });
    if (!res.ok) { var b = await res.text(); throw new Error('Akeneo attributes error: ' + res.status + ' ' + b); }
    var data = await res.json();
    (data._embedded && data._embedded.items || []).forEach(function(a) {
      attributes.push({ code: a.code, label_en: (a.labels && (a.labels.en_US || a.labels.en)) || a.code, type: a.type });
    });
    nextUrl = (data._links && data._links.next && data._links.next.href) || null;
    pages++;
  }
  return attributes;
}

async function fetchProductData(sku, token) {
  var headers = { Authorization: 'Bearer ' + token };
  var productRes = await makeRequest(AKENEO_BASE_URL + '/api/rest/v1/products/' + encodeURIComponent(sku), { headers: headers });
  if (productRes.ok) { var p = await productRes.json(); return buildUnitViews(p.values || {}, p.categories || []); }
  if (productRes.status !== 404) throw new Error('Akeneo product error for ' + sku + ': ' + productRes.status);

  var modelRes = await makeRequest(AKENEO_BASE_URL + '/api/rest/v1/product-models/' + encodeURIComponent(sku), { headers: headers });
  if (!modelRes.ok) { console.warn('Not found in Akeneo: ' + sku); return []; }

  var model = await modelRes.json();
  var modelValues = model.values || {};
  var modelCats = model.categories || [];
  var search = encodeURIComponent(JSON.stringify({ parent: [{ operator: '=', value: sku }] }));
  var varRes = await makeRequest(AKENEO_BASE_URL + '/api/rest/v1/products?search=' + search + '&limit=25', { headers: headers });
  if (!varRes.ok) return [{ values: Object.assign({}, modelValues, { __categories: modelCats }) }];

  var varData = await varRes.json();
  var variants = (varData._embedded && varData._embedded.items) || [];
  if (variants.length === 0) return [{ values: Object.assign({}, modelValues, { __categories: modelCats }) }];
  var merged = variants.map(function(v) { return { values: Object.assign({}, modelValues, v.values || {}, { __categories: (v.categories && v.categories.length ? v.categories : modelCats) }) }; });
  return sortVariantsBySize(merged);
}

// ── OpenAI column mapping ─────────────────────────────────────────────

async function getColumnMapping(headerCols, attributes) {
  var columns = headerCols.map(function(h) {
    return h.hint ? { name: h.header, hint: h.hint.replace(/\n/g, ' | ') } : { name: h.header };
  });
  var systemPrompt = 'You are a data mapping expert. Map each Excel column header to the BEST-matching Akeneo attribute code.\n' +
    'Rules:\n' +
    '- Map as many columns as you reasonably can (commodity group, product hierarchy, supplier, material/season/brand/colour, classifications, weight, dimensions, etc.). Only use attribute codes from the provided list — never invent a code. Return null for a column ONLY when nothing in the list plausibly matches.\n' +
    '- Your job is to choose WHICH attribute a column maps to, not to invent factual values. Do not infer values from outside/world knowledge (e.g. country of origin, brand facts); a separate step fills those hardcoded fields.\n' +
    '- The "hint" field (when present) describes the expected values or format for that column.\n' +
    '- If hint lists code options (e.g. "PC = PIECE | INB = BOX"), map to simpleselect/text — NEVER a metric attribute.\n' +
    '- NEVER map a date column (hint like "ddmmjjjj", "Geldig van", valid-from, datum). Return null for any date column.\n' +
    '- If hint is numeric (e.g. "max 3 decimals"), map to decimal/metric.\n' +
    '- Map gross weight, length, width, height and size/dimension columns to the matching metric or decimal Akeneo attributes.\n' +
    '- For MAKTX_NL, MAKTX_FR, MAKTX_EN, MAKTX_DE: map to the COMMERCIAL product name (catalog/marketing name, not SAP internal name). Prefer attributes whose code contains "name" or "description" and that have locale-specific values (localizable=true).\n' +
    '- NEVER map any column to a price attribute (purchase price, sales price, standard price, recommended price, prijs, prix, stprs, einkaufspreis). Return null for any price-related column.\n' +
    'Return ONLY valid JSON: { "<column_name>": "<akeneo_attribute_code_or_null>" } for every column.';
  var res = await makeRequest('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { Authorization: 'Bearer ' + OPENAI_API_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'gpt-4o',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: JSON.stringify({ excel_columns: columns, akeneo_attributes: attributes.slice(0, 300).map(function(a) { return { code: a.code, label: a.label_en, type: a.type }; }) }) }
      ],
      response_format: { type: 'json_object' },
      temperature: 0
    })
  });
  if (!res.ok) { var b = await res.text(); throw new Error('OpenAI error: ' + res.status + ' ' + b); }
  var data = await res.json();
  var content = data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content;
  if (!content) throw new Error('OpenAI returned no content');
  try { return JSON.parse(content); } catch(e) { throw new Error('OpenAI returned non-JSON: ' + content.substring(0, 200)); }
}

// ── Main ──────────────────────────────────────────────────────────────

var inputJson = $input.first().json;
var headerCols       = inputJson.headerCols;
var rows             = inputJson.rows;
var originalBuffer   = inputJson.originalBuffer;
var originalFileName = inputJson.originalFileName || 'enriched.xlsx';

var workbook = new ExcelJS.Workbook();
await workbook.xlsx.load(Buffer.from(originalBuffer, 'base64'));
var worksheet = workbook.worksheets[0];

var akeneoToken  = await getAkeneoToken();
var attributes   = await fetchAkeneoAttributes(akeneoToken);
var columnMapping = await getColumnMapping(headerCols, attributes);

var skuMap = new Map();
for (var row of rows) {
  if (!skuMap.has(row.sku)) skuMap.set(row.sku, []);
  skuMap.get(row.sku).push(row.rowNum);
}

for (var [sku, rowNumbers] of skuMap) {
  var variantList = await fetchProductData(sku, akeneoToken);
  if (variantList.length === 0) continue;

  for (var i = 0; i < rowNumbers.length; i++) {
    var rowNum  = rowNumbers[i];
    var variant = variantList[i % variantList.length];
    for (var col of headerCols) {
      if (BLOCKED_HEADERS.has(col.header)) continue;
      if (isDateColumn(col.header, col.hint)) continue;
      var hardcoded = getHardcodedValue(col.header, col.hint, variant.values);
      if (hardcoded !== undefined) {
        if (hardcoded !== null) worksheet.getRow(rowNum).getCell(col.colNum).value = hardcoded;
        continue;
      }
      if (isYesNoColumn(col.header, col.hint)) {
        var flagCode = columnMapping[col.header];
        var flagVal = (flagCode && variant.values[flagCode]) ? extractValue(variant.values[flagCode]) : null;
        worksheet.getRow(rowNum).getCell(col.colNum).value = toYesNo(flagVal);
        continue;
      }
      var akeneoCode = MAKTX_LOCALES[col.header] ? MAKTX_HARDCODED_ATTR : columnMapping[col.header];
      if (!akeneoCode || !variant.values[akeneoCode]) continue;
      var locale = MAKTX_LOCALES[col.header];
      var value = locale
        ? extractLocalizedValue(variant.values[akeneoCode], locale)
        : extractValue(variant.values[akeneoCode]);
      if (value !== null && value !== undefined) {
        worksheet.getRow(rowNum).getCell(col.colNum).value = value;
      }
    }
  }
}

// Flatten shared formulas — prevents ExcelJS write error:
// 'Shared Formula master must exist above and or left of clone'
// Clone cells use { sharedFormula: 'addr', result } with NO formula key — must be handled separately.
workbook.worksheets.forEach(function(ws) {
  ws.eachRow({ includeEmpty: false }, function(row) {
    row.eachCell({ includeEmpty: false }, function(cell) {
      var v = cell.value;
      if (v && typeof v === 'object') {
        if ('sharedFormula' in v) {
          // Clone cell: drop shared-formula reference, keep result as static value
          cell.value = (v.result !== undefined && v.result !== null) ? v.result : null;
        } else if ('formula' in v) {
          // Master or regular formula: strip shareType/ref metadata
          cell.value = { formula: v.formula, result: v.result };
        }
      }
    });
  });
});

workbook.worksheets.forEach(function(ws) {
  if (ws.conditionalFormattings) {
    ws.conditionalFormattings = ws.conditionalFormattings
      .map(function(cf) { cf.rules = (cf.rules || []).filter(function(r) { return r.formulae !== undefined || ['expression','cellIs','containsText','timePeriod'].indexOf(r.type) === -1; }); return cf; })
      .filter(function(cf) { return cf.rules.length > 0; });
  }
});

var outputBuffer = await workbook.xlsx.writeBuffer();
var base64Data   = Buffer.from(outputBuffer).toString('base64');

return [{ json: { success: true, fileName: originalFileName }, binary: { data: { data: base64Data, mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', fileName: originalFileName, fileExtension: 'xlsx' } } }];
